            if (department && r.department !== department)
                return false;
            return true;
        });
    }, [rows, keyword, status, department]);
    const total = filtered.length;
    const paged = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);
    const columns: ColumnDef<WorkOrder>[] = [
        {
            accessorKey: "id",
            header: "Ticket ID",
