};
const STATUS_TAG_TONE: Record<Ticket["status"], "neutral" | "warning" | "success" | "danger"> = {
    open: "neutral",
    in_progress: "warning",
    resolved: "success",
    closed: "danger",
};
const PRIORITY_TONE: Record<Ticket["priority"], "danger" | "warning" | "neutral"> = {
    "High": "danger",
    "Medium": "warning",
    "Low": "neutral",
};
const HISTORY: TimelineItemProps[] = [
    {
